<?php
namespace App\Models; use App\Models\Concerns\InvalidatesWorkProcesses; use Illuminate\Database\Eloquent\{Builder,Factories\HasFactory,Model}; use Illuminate\Database\Eloquent\Relations\{BelongsToMany,HasMany}; class WorkProcess extends Model { use HasFactory,InvalidatesWorkProcesses; protected $fillable=['title','slug','eyebrow','short_description','overview','icon','featured_image_path','featured_image_alt','template','hero_style','status','is_featured','display_order','published_at','scheduled_for','archived_at','primary_cta_label','primary_cta_url','secondary_cta_label','secondary_cta_url','meta_title','meta_description','canonical_url','og_title','og_description','og_image_path','robots_index','robots_follow','created_by','updated_by']; protected function casts():array{return ['is_featured'=>'boolean','robots_index'=>'boolean','robots_follow'=>'boolean','published_at'=>'datetime','scheduled_for'=>'datetime','archived_at'=>'datetime'];} public function stages():HasMany{return $this->hasMany(WorkProcessStage::class)->orderBy('display_order');} public function relatedSolutions():BelongsToMany{return $this->belongsToMany(Solution::class,'work_process_solution_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedProducts():BelongsToMany{return $this->belongsToMany(Product::class,'work_process_product_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedIndustries():BelongsToMany{return $this->belongsToMany(Industry::class,'work_process_industry_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedPages():BelongsToMany{return $this->belongsToMany(Page::class,'work_process_page_relations')->withPivot('display_order')->orderByPivot('display_order');} public function navigationItems():HasMany{return $this->hasMany(NavigationItem::class);} public function homepageSections():HasMany{return $this->hasMany(HomepageSection::class);} public function scopePubliclyVisible(Builder $q):Builder{return $q->whereNull('archived_at')->whereNotNull('short_description')->where(fn(Builder $q)=>$q->where(fn(Builder $x)=>$x->where('status','published')->whereNotNull('published_at')->where('published_at','<=',now()))->orWhere(fn(Builder $x)=>$x->where('status','scheduled')->whereNotNull('scheduled_for')->where('scheduled_for','<=',now())));} public function isPubliclyVisible():bool{return $this->archived_at===null&&trim((string)$this->short_description)!==''&&(($this->status==='published'&&$this->published_at?->lte(now()))||($this->status==='scheduled'&&$this->scheduled_for?->lte(now())));}}
